from tool.impl.file.tool_tree import IGNORED, IGNORED_EXT
import hashlib
import os

# A bigger file is a dump (a data file, a bundle), not something to read passage by passage
MAX_FILE_SIZE: int = 1_000_000
# A file with a longer line is minified or generated: no passage of it is worth reading
MAX_LINE_LEN: int = 2000

# Generated by a tool, huge, and never what a question is about
LOCKFILES: frozenset[str] = frozenset({
    "package-lock.json", "yarn.lock", "pnpm-lock.yaml", "poetry.lock", "Pipfile.lock", "Cargo.lock", "composer.lock",
    "go.sum"
})
SKIPPED_EXT: frozenset[str] = frozenset({".map", ".lock", ".svg"})
# Keys and environment files: what the model must never be handed back from a folder the user indexed
SECRET_EXT: frozenset[str] = frozenset({".pem", ".key", ".p12", ".pfx", ".keystore", ".jks"})

# A file made by a program (a grid of settings, a dump, a table): its passages all look alike, and take the places of
# the others in every search. It says so in its first lines, or its lines repeat: a long file with fewer distinct
# lines than this share (a file written by hand has most of its lines distinct)
GENERATED_MARKS: tuple[str, ...] = ("@generated", "do not edit", "auto-generated", "autogenerated", "automatically generated")
GENERATED_HEAD : int   = 5
GENERATED_LINES: int   = 500
GENERATED_RATIO: float = 0.10

def skipped(name: str) -> bool:
    """ Whether a file is left out by its name: a link to nothing to read, a lockfile, a key, louis' own files """
    ext: str = os.path.splitext(name)[1].lower()
    return (name in LOCKFILES or ext in IGNORED_EXT or ext in SKIPPED_EXT or ext in SECRET_EXT
            or name.startswith((".env", "id_rsa", "id_ed25519", "louis.")) or name.endswith(".min.js"))

def scan(root: str) -> list[str]:
    """ The files of a folder that may be indexed, in order: dependencies, .git, links and big files left out """
    found: list[str] = []
    # os.walk does not go down into links to folders: nothing outside the folder is reached
    for folder, dirs, files in os.walk(root):
        dirs[:] = sorted(d for d in dirs if d not in IGNORED)
        for name in sorted(files):
            path: str = os.path.join(folder, name)
            if skipped(name) or os.path.islink(path) or not os.path.isfile(path):
                continue
            try:
                if os.path.getsize(path) > MAX_FILE_SIZE:
                    continue
            except OSError:
                continue
            found.append(path)
    return found

def generated(text: str, ratio: float = GENERATED_RATIO) -> str | None:
    """ Why a text looks made by a program, None if it looks written by hand. ratio 0 only reads the marks """
    head: str = "\n".join(text.splitlines()[:GENERATED_HEAD]).lower()
    mark: str | None = next((mark for mark in GENERATED_MARKS if mark in head), None)
    if mark is not None:
        return f"marqué « {mark} »"
    lines: list[str] = [line.strip() for line in text.splitlines() if line.strip()]
    if ratio and len(lines) >= GENERATED_LINES:
        distinct: float = len(set(lines)) / len(lines)
        if distinct < ratio:
            return f"{distinct:.0%} de lignes distinctes sur {len(lines)}"
    return None

def load(path: str) -> tuple[str, str] | None:
    """ The text of a file and the hash of its content, None if it is not text to read (binary, minified, empty) """
    try:
        with open(path, "rb") as file:
            data: bytes = file.read()
        text: str = data.decode("utf-8")
    except (OSError, UnicodeDecodeError):
        return None
    if not text.strip() or "\0" in text or any(len(line) > MAX_LINE_LEN for line in text.splitlines()):
        return None
    return text, hashlib.sha1(data).hexdigest()
